Here's how to create a simple linked list in Python:
python
class Node:
    def _init(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init_(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

ll = LinkedList()
ll.append(10)
ll.append(20)

